// Pure-Java Sudoku engine: solver, rater, generator, hints, rules, and the build-time puzzle bank.
plugins {
    `java-library`
}

java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

tasks.withType<JavaCompile>().configureEach {
    options.release.set(17)
    options.encoding = "UTF-8"
}

dependencies {
    testImplementation("junit:junit:4.13.2")
}

// The puzzle bank is generated by :app's generatePuzzleBank task (runs BankBuilder from this module).
